-- Editing a program exercise's description per patient (decided with the
-- person 2026-10-14). Generated by drizzle-kit, then HAND-EDITED (marked
-- "HAND-EDITED" below), the same way as 0032.
--
-- Since 0032 each session's checklist row keeps a COPY of its exercise's name
-- and prescription, taken when the session starts. The DESCRIPTION — muscles,
-- equipment, instructions — was still only on the program exercise, which a
-- practitioner can now edit for one patient. So a session opened later would
-- have shown TODAY's instructions next to its own sets. The four columns
-- below complete the copy: a session row now says everything it was given.
--
-- Why hand-edited: drizzle-kit writes `ADD COLUMN … NOT NULL`, which fails on
-- a table that already has rows (every existing row would start NULL). So:
-- add the columns nullable, fill them, then make them NOT NULL. They have no
-- DEFAULT, on purpose (sessions.schema.ts): a future insert that forgets the
-- copy must fail, not record "no instructions".

-- HAND-EDITED: added WITHOUT NOT NULL here.
ALTER TABLE "session_exercises" ADD COLUMN "primary_muscles" text[];--> statement-breakpoint
ALTER TABLE "session_exercises" ADD COLUMN "secondary_muscles" text[];--> statement-breakpoint
ALTER TABLE "session_exercises" ADD COLUMN "equipment" text[];--> statement-breakpoint
ALTER TABLE "session_exercises" ADD COLUMN "instructions" text[];--> statement-breakpoint

-- HAND-EDITED: the backfill. Existing rows get the program exercise's
-- description AS IT IS TODAY — the best information there is (what each old
-- session was shown was never stored; the same compromise as 0032's
-- backfill). Nothing could edit a program's description from the app before
-- this step, so today's value is, in practice, the one they were given.
--
-- This UPDATE runs as the tables' owner, which the guard below exempts —
-- and the guard as it stands (0033) doesn't know these columns anyway.
UPDATE "session_exercises" AS se
SET "primary_muscles" = pe."primary_muscles",
    "secondary_muscles" = pe."secondary_muscles",
    "equipment" = pe."equipment",
    "instructions" = pe."instructions"
FROM "assigned_program_exercises" AS pe
WHERE pe."id" = se."assigned_program_exercise_id";--> statement-breakpoint

-- HAND-EDITED: now every row has them (the foreign key guarantees each row
-- found its program exercise, whose four columns are NOT NULL).
ALTER TABLE "session_exercises" ALTER COLUMN "primary_muscles" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "session_exercises" ALTER COLUMN "secondary_muscles" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "session_exercises" ALTER COLUMN "equipment" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "session_exercises" ALTER COLUMN "instructions" SET NOT NULL;--> statement-breakpoint

-- HAND-EDITED: the database's half — the copy is FIXED, like the
-- prescription. 0033's guard compares a fixed list of columns between the
-- row before (OLD) and after (NEW) an update; a column not in that list can
-- be changed freely. So the function is re-created with the four new
-- columns in BOTH rows of the comparison. Everything else is 0033's, word
-- for word (the owner exempt; SQLSTATE 23514 with the same CONSTRAINT name,
-- which HttpExceptionFilter and the tests already know).
--
-- CREATE OR REPLACE keeps the function's identity, so the trigger created in
-- 0033 (session_exercise_prescription_guard) calls the new body with no
-- change of its own. Drizzle doesn't track functions or triggers, which is
-- why this goes in a hand-edited migration rather than the schema.
CREATE OR REPLACE FUNCTION guard_session_exercise_prescription() RETURNS trigger
  LANGUAGE plpgsql AS $$
BEGIN
  IF pg_has_role(
       current_user,
       (SELECT relowner FROM pg_class WHERE oid = TG_RELID),
       'MEMBER'
     ) THEN
    RETURN NEW;
  END IF;
  IF (NEW.session_id, NEW.assigned_program_exercise_id, NEW.name, NEW.sets,
      NEW.reps, NEW.duration_in_seconds, NEW.weight, NEW.weight_unit,
      NEW.notes, NEW.primary_muscles, NEW.secondary_muscles, NEW.equipment,
      NEW.instructions)
     IS DISTINCT FROM
     (OLD.session_id, OLD.assigned_program_exercise_id, OLD.name, OLD.sets,
      OLD.reps, OLD.duration_in_seconds, OLD.weight, OLD.weight_unit,
      OLD.notes, OLD.primary_muscles, OLD.secondary_muscles, OLD.equipment,
      OLD.instructions) THEN
    RAISE EXCEPTION 'What session exercise % prescribed can no longer change', OLD.id
      USING ERRCODE = 'check_violation',
            CONSTRAINT = 'session_exercise_prescription_fixed',
            TABLE = TG_TABLE_NAME;
  END IF;
  RETURN NEW;
END
$$;